SELECT s.id, s.media_id, s.app_id, s.name, s.name_alise, s.ad_scene, s.ad_size, s.ssp_pay_type, s.ssp_deal_ratio, s.fixed_price, s.ad_image, s.enable, s.creator, s.create_time, s.updater, s.update_time, s.deleted, s.tenant_id, m.media_company_short as mediaShortName, a.access_type as accessType, a.name as appName, a.os_type as osType
FROM ssp_slot_info as s LEFT JOIN ssp_media as m ON m.id = s.media_id AND m.deleted = 0 AND m.enable = 1 LEFT JOIN ssp_app as a ON a.id = s.app_id AND a.deleted = 0 AND a.enable = 1
s.deleted = 0
AND s.id = #{reqVO.id}
AND s.media_id = #{reqVO.mediaId}
AND s.app_id = #{reqVO.appId}
AND s.name LIKE CONCAT('%', #{reqVO.name}, '%')
AND s.name_alise LIKE CONCAT('%', #{reqVO.nameAlise}, '%')
AND s.ad_scene = #{reqVO.adScene}
AND s.ssp_pay_type = #{reqVO.sspPayType}
AND s.enable = #{reqVO.enable}
AND s.create_time BETWEEN #{reqVO.createTime[0]} AND #{reqVO.createTime[1]}
AND s.update_time BETWEEN #{reqVO.updateTime[0]} AND #{reqVO.updateTime[1]}
ORDER BY s.id DESC LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*)
FROM ssp_slot_info as s
    LEFT JOIN ssp_media as m
        ON  m.id = s.media_id AND m.deleted = 0 AND m.enable = 1
    LEFT JOIN ssp_app as a
        ON a.id = s.app_id AND a.deleted = 0 AND a.enable = 1

    s.deleted = 0

